import shlex
import ast

class Node:
    def __init__(self, val, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def build_ast(tokens):
    nodes = []
    for token in tokens:
        if token == '(':
            nodes.append(Node('('))
        elif token == ')':
            while nodes[-1].val != '(':
                nodes.append(Node(')'))
                nodes = nodes[:-1]
            nodes.append(Node(')'))
        elif token in '+-*/':
            while nodes and nodes[-1].val in '+-*/':
                nodes.append(Node(token))
                nodes = nodes[:-1]
            nodes.append(Node(token))
        else:
            nodes.append(Node(int(token)))
    return nodes

def evaluate(node):
    if node.val == '+':
        return evaluate(node.left) + evaluate(node.right)
    elif node.val == '-':
        return evaluate(node.left) - evaluate(node.right)
    elif node.val == '*':
        return evaluate(node.left) * evaluate(node.right)
    elif node.val == '/':
        return evaluate(node.left) // evaluate(node.right)
    else:
        return node.val

def solve(expr):
    lexer = shlex.shlex(expr)
    lexer.wordchars += '+-*/()'
    tokens = list(lexer)
    ast = build_ast(tokens)
    return evaluate(ast[0])
